verify.cmd:
node -e 'const fs=require("fs")
const fail=(m)=>{console.error(m);process.exit(1)}
const norm=(s)=>s.replace(/\/\*[\s\S]*?\*\//g," ").replace(/^\s*\/\/.*$/gm," ")
const rd=(f)=>{try{return norm(fs.readFileSync(f,"utf8"))}catch(e){return null}}
const or=rd("lib/commerce/orders.ts")
if(or===null)process.exit(79)
if(!/commerce_order_transfers/.test(or))fail("the orders module never reads the transfer ledger, so a seller never sees their share of a split order")
if(!/\.eq\(\s*"owner_kind"\s*,\s*seller\.kind\s*\)/.test(or.replace(/\x27/g,"\""))||!/items\.filter\(/.test(or))fail("a seller read of a split order is not bound to that seller kind and lines, so one seller can be shown another seller share")
if(!/share/.test(or))fail("an order is returned without the seller share, so a Space Shop would show the whole cart as its own")
for(const p of ["app/(main)/spaces/[slug]/settings/shop/orders-tab.tsx","app/(main)/(marketplace)/market/manage/page.tsx"])if(!/<OrderShareNote\b/.test(rd(p)||""))fail(p+" lists a seller sales without their share of a split order")
const ap=rd("app/(main)/admin/marketplace/orders/page.tsx")||"",aa=rd("app/(main)/admin/marketplace/actions.ts")||""
if(!/<OrderTransferLedger\b/.test(ap)||!/data-order-transfers/.test(rd("components/marketplace/order-transfer-ledger.tsx")||""))fail("the operator orders page shows no transfer state, so a stuck transfer is a log line nobody reads")
if(!/export async function retryOrderTransferAction\(/.test(aa))fail("an operator cannot send a failed transfer again from the product")
const rt=rd("lib/commerce/transfer-retry.ts")||""
if(!/executePlannedTransfers\(/.test(rt)||!/attempts:\s*MAX_TRANSFER_ATTEMPTS\s*-\s*1/.test(rt))fail("the operator retry does not reopen a stuck row through the one executor with attempts above zero, so it skips the adoption lookup that stops a second payment")
console.log("ok")'
